import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarEmissor } from './solution.mjs';

test('subscribe + emit: o inscrito recebe o evento e emit devolve 1', () => {
  const emissor = criarEmissor();
  const recebidos = [];
  emissor.subscribe((evento) => recebidos.push(evento));
  assert.equal(emissor.emit('pedido-criado'), 1);
  assert.deepEqual(recebidos, ['pedido-criado']);
});

test('múltiplos inscritos são avisados na ordem da inscrição', () => {
  const emissor = criarEmissor();
  const ordem = [];
  emissor.subscribe(() => ordem.push('primeiro'));
  emissor.subscribe(() => ordem.push('segundo'));
  emissor.emit({ tipo: 'pagamento' });
  assert.deepEqual(ordem, ['primeiro', 'segundo']);
});

test('a função devolvida por subscribe DESCADASTRA o inscrito', () => {
  const emissor = criarEmissor();
  const recebidos = [];
  const descadastrar = emissor.subscribe((evento) => recebidos.push(evento));
  emissor.emit('um');
  descadastrar();
  assert.equal(emissor.emit('dois'), 0); // ninguém mais inscrito
  assert.deepEqual(recebidos, ['um']);
});

test('subscribe recusa quem não é função; emit sem inscritos devolve 0', () => {
  const emissor = criarEmissor();
  assert.throws(() => emissor.subscribe('não sou função'));
  assert.equal(emissor.emit('evento'), 0);
});

