// OBSERVER: objetos interessados (subscribers) se cadastram e são avisados
// quando um evento acontece — o emissor não precisa conhecer ninguém.
export function criarEmissor() {
  const inscritos = []; // a lista de interessados mora aqui dentro

  return {
    subscribe(callback) {
      if (typeof callback !== 'function') {
        throw new Error('subscriber precisa ser uma função');
      }
      inscritos.push(callback);
      // Devolve uma função para DESCADASTRAR — o padrão também precisa de saída.
      return () => {
        const posicao = inscritos.indexOf(callback);
        if (posicao !== -1) {
          inscritos.splice(posicao, 1);
        }
      };
    },

    emit(evento) {
      // Avisa todos os inscritos, na ordem de inscrição, com o mesmo evento.
      for (const inscrito of inscritos) {
        inscrito(evento);
      }
      return inscritos.length; // quantos foram avisados
    },
  };
}
